function validate([s]) {
  if (typeof s !== 'string' || s.length < 3 || s.length > 50000) return 's needs 3 to 50,000 characters.';
  if (!/^[abc]+$/.test(s)) return "s may contain only 'a', 'b' and 'c'.";
  return null;
}

