function numberOfSubstrings(s) {
  const count = [0, 0, 0];
  let left = 0;
  let total = 0;
  for (let right = 0; right < s.length; right++) {
    count[s.charCodeAt(right) - 97]++;
    while (count[0] > 0 && count[1] > 0 && count[2] > 0) {
      count[s.charCodeAt(left) - 97]--;
      left++;
    }
    total += left;
  }
  return total;
}

