function numberOfSubstrings(s) {
  let answer = 0;
  for (let i = 0; i < s.length; i++) {
    const seen = new Set();
    for (let j = i; j < s.length; j++) {
      seen.add(s[j]);
      if (seen.size === 3) answer++;
    }
  }
  return answer;
}

