function generate(rand, size) {
  const n = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 3 + Math.floor(rand() * 10);
  const mode = Math.floor(rand() * 4);
  const pick = letters => letters[Math.floor(rand() * letters.length)];
  let s = '';
  if (mode === 0) {
    // Uniformly random letters.
    while (s.length < n) s += pick('abc');
  } else if (mode === 1) {
    // Runs of one letter, so windows must stretch far.
    while (s.length < n) s += pick('abc').repeat(1 + Math.floor(rand() * (size === 'large' ? 300 : 4)));
  } else if (mode === 2) {
    // Mostly 'a' with rare 'b' and 'c'.
    while (s.length < n) s += rand() < 0.9 ? 'a' : pick('bc');
  } else {
    // Only two distinct letters (the answer is 0), occasionally broken by one third letter.
    const two = pick(['ab', 'bc', 'ac']);
    while (s.length < n) s += pick(two);
    if (rand() < 0.5) {
      const third = 'abc'.split('').find(c => !two.includes(c));
      const at = Math.floor(rand() * n);
      s = s.slice(0, at) + third + s.slice(at + 1);
    }
  }
  return [s.slice(0, n)];
}
